# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 106-134. AYETLERDE MED UYGULAMALARI (KK.6.2.2)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Medd-i Lâzım (Kalıcı Sükûn)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Med harfinden sonra lâzım sükûn</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">(cezim veya şedde) gelir.</text>\n  <text x="125" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Uzatma: 4 Elif (Vacip)</text>\n  <text x="125" y="180" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">تُحَاجُّونَنَا · الضَّالِّينَ · الم</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" fill="#2563eb">Durulsa da geçilse de 4 elif uzatılır.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Medd-i Ârız (Durak Sükûnu)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Med harfinden sonra durak sebebiyle</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">geçici (ârızî) sükûn oluşur.</text>\n  <text x="350" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Uzatma: 1, 2, 3 veya 4 Elif (Caiz)</text>\n  <text x="350" y="180" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">الْعَالَمِينَ \u06dd · الرَّحِيمُ \u06dd</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#166534">Geçilirse Medd-i Tabiî (1 elif) olur.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Medd-i Lîn (Yumuşak Med)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#713f12">• Üstünlü harften sonra cezmli</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11.5" fill="#713f12">وْ / يْ (lîn harfi) + sükûn gelir.</text>\n  <text x="575" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Durulduğunda Yumuşak Uzatılır</text>\n  <text x="575" y="180" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">الْبَيْتِ \u06dd · خَوْفٍ \u06dd · شَيْءٍ \u06dd</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#854d0e">Geçilirse uzatma yapılmaz.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN KISSALARINDAN HAYATA: HZ. YUNUS\'UN (AS) İMTİHANI (KK.6.2.3)</text>\n  <rect x="20" y="50" width="150" height="185" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="95" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">1. Ninova\'da Tebliğ</text>\n  <text x="95" y="105" text-anchor="middle" font-size="11" fill="#831843">Asurluların başkenti</text>\n  <text x="95" y="125" text-anchor="middle" font-size="11" fill="#831843">Ninova halkını tevhid</text>\n  <text x="95" y="145" text-anchor="middle" font-size="11" fill="#831843">inancına davet etti.</text>\n  <text x="95" y="175" text-anchor="middle" font-size="11" fill="#9d174d">İzinsiz şehirden</text>\n  <text x="95" y="195" text-anchor="middle" font-size="11" fill="#9d174d">ayrılıp gemiye bindi.</text>\n\n  <rect x="190" y="50" width="150" height="185" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="265" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">2. Ninova\'nın Tövbesi</text>\n  <text x="265" y="105" text-anchor="middle" font-size="11" fill="#581c87">Azap belirtilerini gören</text>\n  <text x="265" y="125" text-anchor="middle" font-size="11" fill="#581c87">Ninova halkı pişman</text>\n  <text x="265" y="145" text-anchor="middle" font-size="11" fill="#581c87">olup samimiyetle</text>\n  <text x="265" y="165" text-anchor="middle" font-size="11" fill="#581c87">Allah\'a yöneldi ve</text>\n  <text x="265" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">azaptan kurtuldu.</text>\n\n  <rect x="360" y="50" width="150" height="185" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="435" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">3. Gemi ve Balık</text>\n  <text x="435" y="105" text-anchor="middle" font-size="11" fill="#155e75">Fırtınada çekilen</text>\n  <text x="435" y="125" text-anchor="middle" font-size="11" fill="#155e75">kur\'ada adı çıktı;</text>\n  <text x="435" y="145" text-anchor="middle" font-size="11" fill="#155e75">denize atılan Hz. Yunus\'u</text>\n  <text x="435" y="165" text-anchor="middle" font-size="11" fill="#155e75">büyük bir balık yuttu</text>\n  <text x="435" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">(Sâhibü\'l-Hût / Zünnûn).</text>\n\n  <rect x="530" y="50" width="150" height="185" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="605" y="75" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">4. Dua ve Kurtuluş</text>\n  <text x="605" y="105" text-anchor="middle" font-size="11" fill="#9a3412">Karanlıklar içinde</text>\n  <text x="605" y="125" text-anchor="middle" font-size="11" fill="#9a3412">hatasını anlayarak</text>\n  <text x="605" y="145" text-anchor="middle" font-size="11" fill="#9a3412">tövbe ve tesbih etti;</text>\n  <text x="605" y="165" text-anchor="middle" font-size="11" fill="#9a3412">duası kabul edilerek</text>\n  <text x="605" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#ea580c">sahile çıkarıldı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. YUNUS\'UN (AS) TÖVBE DUASI VE KISSADAN İLKELER (ENBİYÂ 87)</text>\n  <rect x="25" y="48" width="650" height="102" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="78" text-anchor="middle" font-size="17" font-weight="bold" fill="#1d4ed8">لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ</text>\n  <text x="350" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Okunuşu: «Lâ ilâhe illâ ente sübhâneke innî küntü mine\'z-zâlimîn.»</text>\n  <text x="350" y="130" text-anchor="middle" font-size="11.5" fill="#1e40af">Anlamı: «Senden başka ilah yoktur. Seni her türlü eksiklikten tenzih ederim. Gerçekten ben kendine yazık edenlerden oldum.»</text>\n\n  <rect x="25" y="162" width="650" height="80" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="185" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hz. Yunus (as) Kıssasından Hayatımıza Yansıyan Mesajlar</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11.5" fill="#14532d">• Görev ve sorumluluklarda sabırlı olmak, aceleci davranmamak · Zorlukta Allah\'tan ümit kesmemek</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11.5" fill="#14532d">• Hatayı fark ettiğimiz anda samimiyetle tövbe etmek · Allah\'ı tesbih ve zikretmeye devam etmek</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
